from pathlib import PurePosixPath
from zipfile import ZipFile

with ZipFile("docs.zip") as archive:
    word_files = sorted(
        name for name in archive.namelist()
        if not name.endswith("/")
        and PurePosixPath(name).suffix.lower() in {".doc", ".docx"}
    )

print(f"Found {len(word_files)} Word files:")
for path in word_files:
    marker = "  <-- possible customer report" if "customer" in path.lower() else ""
    print(f"{path}{marker}")
